#include <bits/stdc++.h>
using namespace std;

struct Node {
    int cnt = 0;
    bool leftCovered = false;
    bool rightCovered = false;
    bool lazy = false;
};

class SegmentTree {
    vector<Node> tree;

    void apply(int node) {
        tree[node].cnt = 1;
        tree[node].leftCovered = true;
        tree[node].rightCovered = true;
        tree[node].lazy = true;
    }

    void pushDown(int node) {
        if (!tree[node].lazy) return;
        apply(node << 1);
        apply(node << 1 | 1);
        tree[node].lazy = false;
    }

    void pushUp(int node) {
        const Node &left = tree[node << 1];
        const Node &right = tree[node << 1 | 1];

        tree[node].cnt = left.cnt + right.cnt;
        if (left.rightCovered && right.leftCovered) {
            --tree[node].cnt;
        }

        tree[node].leftCovered = left.leftCovered;
        tree[node].rightCovered = right.rightCovered;
    }

    void update(int node, int left, int right, int queryLeft, int queryRight) {
        if (queryLeft <= left && right <= queryRight) {
            apply(node);
            return;
        }

        pushDown(node);
        int mid = left + (right - left) / 2;

        if (queryLeft <= mid) {
            update(node << 1, left, mid, queryLeft, queryRight);
        }
        if (queryRight > mid) {
            update(node << 1 | 1, mid + 1, right, queryLeft, queryRight);
        }

        pushUp(node);
    }

public:
    explicit SegmentTree(int size) : tree(size * 4 + 5) {}

    void update(int size, int left, int right) {
        update(1, 0, size - 1, left, right);
    }

    int count() const {
        return tree[1].cnt;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<long long> left(n), right(n);
    vector<long long> coordinates;
    coordinates.reserve(3LL * n);

    for (int i = 0; i < n; ++i) {
        cin >> left[i] >> right[i];
        --right[i];

        if (left[i] <= right[i]) {
            coordinates.push_back(left[i]);
            coordinates.push_back(right[i]);
            coordinates.push_back(right[i] + 1);
        }
    }

    sort(coordinates.begin(), coordinates.end());
    coordinates.erase(unique(coordinates.begin(), coordinates.end()), coordinates.end());

    if (coordinates.empty()) {
        for (int i = 0; i < n; ++i) {
            cout << 0 << '\n';
        }
        return 0;
    }

    SegmentTree tree(static_cast<int>(coordinates.size()));

    for (int i = 0; i < n; ++i) {
        if (left[i] <= right[i]) {
            int compressedLeft = lower_bound(
                coordinates.begin(), coordinates.end(), left[i]
            ) - coordinates.begin();

            int compressedRight = lower_bound(
                coordinates.begin(), coordinates.end(), right[i]
            ) - coordinates.begin();

            tree.update(static_cast<int>(coordinates.size()),
                        compressedLeft, compressedRight);
        }

        cout << tree.count() << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Node {
    int cnt = 0;
    bool leftCovered = false;
    bool rightCovered = false;
    bool fullyCovered = false;
};

class SegmentTree {
    vector<Node> tree;

    void pull(int rt) {
        const Node &left = tree[rt << 1];
        const Node &right = tree[rt << 1 | 1];

        tree[rt].cnt = left.cnt + right.cnt;
        if (left.rightCovered && right.leftCovered) {
            --tree[rt].cnt;
        }

        tree[rt].leftCovered = left.leftCovered;
        tree[rt].rightCovered = right.rightCovered;
        tree[rt].fullyCovered = left.fullyCovered && right.fullyCovered;
    }

    void update(int rt, int l, int r, int ql, int qr) {
        if (tree[rt].fullyCovered) return;

        if (ql <= l && r <= qr) {
            tree[rt].cnt = 1;
            tree[rt].leftCovered = true;
            tree[rt].rightCovered = true;
            tree[rt].fullyCovered = true;
            return;
        }

        int mid = l + (r - l) / 2;
        if (ql <= mid) update(rt << 1, l, mid, ql, qr);
        if (qr > mid) update(rt << 1 | 1, mid + 1, r, ql, qr);
        pull(rt);
    }

public:
    explicit SegmentTree(int n) : tree(4 * n + 5) {}

    void update(int n, int l, int r) {
        if (l <= r) update(1, 1, n, l, r);
    }

    int count() const {
        return tree[1].cnt;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> l(n), r(n);
    vector<int> coordinates;
    coordinates.reserve(3 * n);

    for (int i = 0; i < n; ++i) {
        cin >> l[i] >> r[i];
        --r[i];

        coordinates.push_back(l[i]);
        coordinates.push_back(r[i]);
        coordinates.push_back(r[i] + 1);
    }

    sort(coordinates.begin(), coordinates.end());
    coordinates.erase(unique(coordinates.begin(), coordinates.end()),
                      coordinates.end());

    int m = static_cast<int>(coordinates.size());
    SegmentTree tree(m);

    for (int i = 0; i < n; ++i) {
        int left = lower_bound(coordinates.begin(), coordinates.end(), l[i])
                   - coordinates.begin() + 1;
        int right = lower_bound(coordinates.begin(), coordinates.end(), r[i])
                    - coordinates.begin() + 1;

        tree.update(m, left, right);
        cout << tree.count() << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Node {
    int cnt = 0;
    bool left = false;
    bool right = false;
    bool lazy = false;
};

class SegmentTree {
    vector<Node> tree;

    void apply(int p) {
        tree[p].cnt = 1;
        tree[p].left = tree[p].right = true;
        tree[p].lazy = true;
    }

    void pushDown(int p) {
        if (!tree[p].lazy) return;
        apply(p << 1);
        apply(p << 1 | 1);
        tree[p].lazy = false;
    }

    void pushUp(int p) {
        const Node &a = tree[p << 1];
        const Node &b = tree[p << 1 | 1];
        tree[p].cnt = a.cnt + b.cnt - (a.right && b.left);
        tree[p].left = a.left;
        tree[p].right = b.right;
    }

    void update(int p, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) {
            apply(p);
            return;
        }

        pushDown(p);
        int mid = l + (r - l) / 2;

        if (ql <= mid) update(p << 1, l, mid, ql, qr);
        if (qr > mid) update(p << 1 | 1, mid + 1, r, ql, qr);

        pushUp(p);
    }

public:
    explicit SegmentTree(int n) : tree(4 * max(1, n) + 5) {}

    void update(int n, int l, int r) {
        if (n > 0 && l <= r) update(1, 0, n - 1, l, r);
    }

    int count() const {
        return tree[1].cnt;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<pair<long long, long long>> intervals(n);
    vector<long long> coordinates;
    coordinates.reserve(3LL * n);

    for (auto &[l, r] : intervals) {
        cin >> l >> r;
        --r;

        coordinates.push_back(l);
        coordinates.push_back(r);
        coordinates.push_back(r + 1);
    }

    sort(coordinates.begin(), coordinates.end());
    coordinates.erase(unique(coordinates.begin(), coordinates.end()),
                      coordinates.end());

    SegmentTree tree(static_cast<int>(coordinates.size()));

    for (const auto &[l, r] : intervals) {
        if (l <= r) {
            int left = lower_bound(coordinates.begin(), coordinates.end(), l) -
                       coordinates.begin();
            int right = lower_bound(coordinates.begin(), coordinates.end(), r) -
                        coordinates.begin();

            tree.update(static_cast<int>(coordinates.size()), left, right);
        }

        cout << tree.count() << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

constexpr int N = 200005;

int n, l[N], r[N];

struct Node {
    int l, r;
    int coll, colr;
    int cnt;
    bool tag;
} tr[N << 2];

struct SegmentTree {
    void build(int rt, int l, int r) {
        tr[rt].l = l;
        tr[rt].r = r;
        if (l == r) return;

        int mid = (l + r) >> 1;
        build(rt << 1, l, mid);
        build(rt << 1 | 1, mid + 1, r);
    }

    void pushdown(int rt) {
        if (!tr[rt].tag) return;

        for (int child : {rt << 1, rt << 1 | 1}) {
            tr[child].tag = true;
            tr[child].cnt = 1;
            tr[child].coll = tr[child].colr = 1;
        }
        tr[rt].tag = false;
    }

    void pushup(int rt) {
        const Node &left = tr[rt << 1];
        const Node &right = tr[rt << 1 | 1];

        tr[rt].cnt = left.cnt + right.cnt;
        tr[rt].coll = left.coll;
        tr[rt].colr = right.colr;

        if (left.colr && right.coll) {
            --tr[rt].cnt;
        }
    }

    void update(int rt, int x, int y) {
        int l = tr[rt].l;
        int r = tr[rt].r;

        if (x <= l && r <= y) {
            tr[rt].cnt = 1;
            tr[rt].tag = true;
            tr[rt].coll = tr[rt].colr = 1;
            return;
        }

        pushdown(rt);
        int mid = (l + r) >> 1;

        if (x <= mid) update(rt << 1, x, min(y, mid));
        if (y > mid) update(rt << 1 | 1, max(x, mid + 1), y);

        pushup(rt);
    }
} tree;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;

    int maxn = 0;
    for (int i = 1; i <= n; ++i) {
        cin >> l[i] >> r[i];
        --r[i];
        maxn = max(maxn, r[i]);
    }

    tree.build(1, 1, maxn);

    for (int i = 1; i <= n; ++i) {
        tree.update(1, l[i], r[i]);
        cout << tr[1].cnt << '\n';
    }

    return 0;
}

